B.abU=new A.c(301,"\u041a\u043e\u0442\u043e\u0432\u043d\u0438\u043a \u043a\u0438\u0441\u0442\u0435\u0432\u0438\u0434\u043d\u044b\u0439","Nepeta racemosa","\u041c\u043d\u043e\u0433\u043e\u043b\u0435\u0442\u043d\u0438\u043a","\u041d\u0435\u0432\u044b\u0441\u043e\u043a\u0438\u0439 \u0430\u0440\u043e\u043c\u0430\u0442\u043d\u044b\u0439 \u043c\u043d\u043e\u0433\u043e\u043b\u0435\u0442\u043d\u0438\u043a \u0441 \u0444\u0438\u043e\u043b\u0435\u0442\u043e\u0432\u043e-\u0441\u0438\u043d\u0438\u043c\u0438 \u0446\u0432\u0435\u0442\u043a\u0430\u043c\u0438 \u043b\u0435\u0442\u043e\u043c.",B.Wh,B.V8,"\u0421\u0440\u0435\u0434\u043d\u0438\u0439",0,0,0.25,"\u0423\u043c\u0435\u0440\u0435\u043d\u043d\u044b\u0439","\u041b\u0435\u0442\u043e","0,1\u20130,5 \u043c",B.TM,B.nL,"\u0421\u0440\u0435\u0434\u043d\u044f\u044f",!1,"\u041d\u0438\u0437\u043a\u043e\u0435",B.VY,"\u041d\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u0430 \u0434\u043b\u044f \u0420\u0424",B.aU,"\u0422\u0440\u0430\u0432\u044f\u043d\u0438\u0441\u0442\u044b\u0439 \u043c\u043d\u043e\u0433\u043e\u043b\u0435\u0442\u043d\u0438\u043a","assets/photos/gbif_d5261f4ffde5364f034b.webp",B.uq)
